// Pure image Runtime contract tests. Caller-owned PNGs are independently
// generated by the MCP harness; no Screen, UI, OCR, network or desktop actions.
const {root, scenario} = Execution.input;
const at = name => File.join(root, name + '.png');
const checks = [];
function same(actual, expected) {
  if (actual === expected) return true;
  if (!actual || !expected || typeof actual !== 'object' || typeof expected !== 'object') return false;
  if (Array.isArray(actual) !== Array.isArray(expected)) return false;
  const keys = Object.keys(expected);
  return Object.keys(actual).length === keys.length && keys.every(key =>
    Object.prototype.hasOwnProperty.call(actual, key) && same(actual[key], expected[key]));
}
function equal(label, actual, expected) {
  checks.push({label, actual, expected, ok: same(actual, expected)});
}
function geometry(block) {
  return {x: block.x, y: block.y, width: block.width, height: block.height, area: block.area};
}
function match(label, source, templates, options, expected) {
  const value = ImageColor.findImage(at(source), Array.isArray(templates) ? templates.map(at) : at(templates), options);
  equal(label, {found: value.found, x: value.x, y: value.y, width: value.width, height: value.height,
    scale: value.scale, confidence: value.confidence, templateIndex: value.templateIndex}, expected);
}
if (scenario === 'blocks') {
  const source = at('blocks');
  equal('fixture red pixel', ImageColor.pixel(source, 8, 6), '#ff0000');
  equal('fixture background pixel', ImageColor.pixel(source, 7, 6), '#ffffff');
  const whole = ImageColor.findColorBlocks(source, '#ff0000', {threshold: 0});
  equal('whole image control', whole.map(geometry), [
    {x: 8, y: 6, width: 8, height: 6, area: 48},
    {x: 24, y: 16, width: 6, height: 6, area: 36},
  ]);
  for (const [label, options, expected] of [
    ['nonzero xy ROI', {x: 5, y: 3, width: 15, height: 13}, {x: 8, y: 6, width: 8, height: 6, area: 48}],
    ['nonzero x ROI', {x: 5, y: 0, width: 15, height: 14}, {x: 8, y: 6, width: 8, height: 6, area: 48}],
    ['nonzero y ROI', {x: 0, y: 3, width: 20, height: 13}, {x: 8, y: 6, width: 8, height: 6, area: 48}],
    ['exact block ROI', {x: 8, y: 6, width: 8, height: 6}, {x: 8, y: 6, width: 8, height: 6, area: 48}],
    ['clipped block ROI', {x: 10, y: 7, width: 6, height: 5}, {x: 10, y: 7, width: 6, height: 5, area: 30}],
  ]) {
    const blocks = ImageColor.findColorBlocks(source, '#ff0000', {...options, threshold: 0});
    equal(label, blocks.map(geometry), [expected]);
    equal(label + ' match', blocks.map(block => block.match), [1]);
  }
  equal('ROI excludes both blocks', ImageColor.findColorBlocks(source, '#ff0000',
    {x: 0, y: 0, width: 6, height: 6, threshold: 0}), []);
  equal('small component threshold retained', ImageColor.findColorBlocks(source, '#ff0000',
    {x: 10, y: 8, width: 5, height: 4, threshold: 0}), []);
} else if (scenario === 'templates') {
  const options = {threshold: 1};
  // Both variants score exactly 1. Later variants have earlier y or x, but
  // the input array priority must win across variants.
  match('array priority before y', 'tie-y', ['blue', 'green'], options,
    {found: true, x: 20, y: 14, width: 4, height: 4, scale: 1, confidence: 1, templateIndex: 0});
  match('array priority before x', 'tie-x', ['blue', 'green'], options,
    {found: true, x: 20, y: 2, width: 4, height: 4, scale: 1, confidence: 1, templateIndex: 0});
  match('reversed variants', 'tie-y', ['green', 'blue'], options,
    {found: true, x: 3, y: 2, width: 4, height: 4, scale: 1, confidence: 1, templateIndex: 0});
  match('strictly better later variant', 'tie-y', ['near-blue', 'green'], options,
    {found: true, x: 3, y: 2, width: 4, height: 4, scale: 1, confidence: 1, templateIndex: 1});
  // Within one template, keep y/x/scale tie breaking independent of scale
  // input order. Solid patches make every perfect score hand-verifiable.
  match('single template y then x', 'single', 'blue', options,
    {found: true, x: 12, y: 2, width: 4, height: 4, scale: 1, confidence: 1, templateIndex: 0});
  match('single template scale tie', 'single', 'blue', {threshold: 1, scales: [1, 0.5]},
    {found: true, x: 12, y: 2, width: 2, height: 2, scale: 0.5, confidence: 1, templateIndex: 0});
  match('single template position before scale', 'scale-position', 'blue', {threshold: 1, scales: [1, 0.5]},
    {found: true, x: 2, y: 2, width: 2, height: 2, scale: 0.5, confidence: 1, templateIndex: 0});
  match('array priority in a nonzero ROI', 'tie-y', ['blue', 'green'],
    {threshold: 1, region: {x: 2, y: 1, width: 27, height: 20}},
    {found: true, x: 20, y: 14, width: 4, height: 4, scale: 1, confidence: 1, templateIndex: 0});
  const multiple = maxResults => ImageColor.findImages(at('single'), at('blue'), {threshold: 1, maxResults})
    .map(({x, y, width, height}) => ({x, y, width, height}));
  const distinct = [
    {x: 12, y: 2, width: 4, height: 4}, {x: 18, y: 2, width: 4, height: 4}, {x: 20, y: 14, width: 4, height: 4},
  ];
  equal('limit of one preserves first match', multiple(1), distinct.slice(0, 1));
  equal('large result ceiling on a small image preserves actual matches', multiple(Number.MAX_SAFE_INTEGER), distinct);
} else if (scenario === 'layout') {
  const options = {cellSize: 2, minRegionArea: 1, maxRegions: 8};
  const plain = ImageColor.analyzeLayout(at('blocks'), options);
  const warning = 'profile is ignored by the generic layout core; pass optional separatorHints from JS or external config instead';
  for (const profile of ['legacy-preset', 'different-preset']) {
    const result = ImageColor.analyzeLayout(at('blocks'), {...options, profile});
    equal('profile warning: ' + profile, result.warnings.filter(value => value === warning), [warning]);
    // The only observable effect is the compatibility warning.
    const normalized = {...result, warnings: result.warnings.filter(value => value !== warning)};
    equal('profile leaves layout unchanged: ' + profile, same(normalized, {...plain, warnings: plain.warnings || []}), true);
  }
  equal('blank profile unchanged', same(ImageColor.analyzeLayout(at('blocks'), {...options, profile: '   '}), plain), true);
} else {
  throw new Error('mcp-image-depth: unknown scenario ' + scenario);
}
const failed = checks.filter(check => !check.ok);
console.log(JSON.stringify({test: 'mcp-image-depth', scenario, executionId: Execution.executionId,
  ok: failed.length === 0, checkCount: checks.length, checks}));
if (failed.length) throw new Error('mcp-image-depth: ' + failed.map(check => check.label).join(', '));
